use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn truncate_chars(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment fetch: the result is deliberately not used, so the output
        // is unaffected; a transport failure is returned as a value and ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = format!("Date: {}\nItems:\n", info.date);
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str(&format!("- {}: {}\n", e.title, e.summary));
        }

        let system = "Write a short overview paragraph (under 500 characters) \
                      introducing today's digest of the listed items. Plain text only.";
        let raw = inference_llm::infer(system, &prompt, "digest");
        let mut overview = truncate_chars(raw.trim(), 600);
        if overview.is_empty() {
            overview = truncate_chars(
                &format!(
                    "Digest for {}: {} item(s) selected.",
                    info.date,
                    selected.entries.len()
                ),
                600,
            );
        }

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
